"""Explicit local configuration; no fallback to the system PostgreSQL service."""
import os
from pathlib import Path
from urllib.parse import urlsplit

from dotenv import load_dotenv

ROOT = Path(__file__).resolve().parents[3]
load_dotenv(ROOT / "BancoModeloUse" / ".env.local", override=False)


def _required(name: str) -> str:
    value = os.getenv(name, "").strip()
    if not value:
        raise ValueError(f"Missing required setting: {name}")
    return value


def db_params(domain: str) -> dict:
    """Read only the isolated cluster configuration generated by local_postgres.py."""
    prefix = f"{domain}_DB_"
    params = {
        "host": _required(prefix + "HOST"),
        "port": int(_required(prefix + "PORT")),
        "dbname": _required(prefix + "NAME"),
        "user": _required(prefix + "USER"),
        "password": _required(prefix + "PASSWORD"),
        "connect_timeout": 5,
    }
    mode = os.getenv("INFERENCE_RUNTIME_MODE", "host")
    allowed = ("db", 5432) if mode == "docker" else ("127.0.0.1", 5544)
    if mode not in {"host", "docker"} or (params["host"], params["port"]) != allowed:
        raise ValueError(f"Inference only accepts the isolated PostgreSQL for {mode} mode")
    expected = {"INDUSTRIAL": "db_industrial", "FINANCEIRO": "db_financeiro"}[domain]
    if params["dbname"] != expected:
        raise ValueError(f"Unexpected {domain} database")
    return params


def app_db_params() -> dict:
    params = db_params("FINANCEIRO")
    params["dbname"] = "db_inference_app"
    return params


def dw_db_params() -> dict:
    """Only the isolated research DW, never the source databases."""
    mode = os.getenv("INFERENCE_RUNTIME_MODE", "host")
    expected = ("db", 5432) if mode == "docker" else ("127.0.0.1", 5544)
    if mode not in {"host", "docker"}:
        raise ValueError("Invalid inference runtime mode")
    host = _required("DW_DB_HOST")
    port = int(_required("DW_DB_PORT"))
    if (host, port) != expected or _required("DW_DB_NAME") != "db_pesquisa_dw":
        raise ValueError("DW connection must target the isolated db_pesquisa_dw")
    return {"host": host, "port": port, "dbname": "db_pesquisa_dw",
            "user": _required("DW_DB_USER"), "password": _required("DW_DB_PASSWORD"),
            "connect_timeout": 5}


def packet_directory() -> Path:
    value = os.getenv("INFERENCE_EVIDENCE_PACKETS_DIR", "").strip()
    if not value:
        return ROOT / "model_evaluation" / ".local" / "packets"
    path = Path(value)
    if not path.is_absolute():
        raise ValueError("Packet directory must be absolute")
    return path


def vllm_url() -> str:
    value = os.getenv("INFERENCE_VLLM_URL", "").strip().rstrip("/")
    if value:
        parsed = urlsplit(value)
        if (parsed.scheme != "https" or not parsed.hostname or parsed.username or
                parsed.password or parsed.query or parsed.fragment or parsed.path not in ("", "/")):
            raise ValueError("INFERENCE_VLLM_URL must be an HTTPS origin without credentials")
    return value
